#!/usr/bin/env python3
"""Turn Carlos's ADPCM golden vectors into a C header for the firmware tests.

Source: phone/test/golden/adpcm_chunks.json, generated by
phone/tools/audio_reference/make_golden.py. Regenerate both together.
"""
import json, sys

d = json.load(open(sys.argv[1]))
chunks = d["chunks_hex"]
pcm = d["input_pcm"]
out = [
    "// Generated by firmware/tools/golden_to_c.py from",
    "// phone/test/golden/adpcm_chunks.json. Do not edit by hand.",
    "//",
    "// Carlos's phone and the Python reference encoder both produce these exact",
    "// bytes. If the firmware encoder produces anything else, the two sides of the",
    "// Bluetooth link disagree and the device's audio will not decode.",
    "#pragma once",
    "",
    "#include <cstdint>",
    "",
    "namespace halo::test::golden {",
    "",
    f"constexpr uint16_t kReq = {d['req']};",
    f"constexpr uint8_t kRev = {d['rev']};",
    f"constexpr uint8_t kSeg = {d['seg']};",
    f"constexpr uint32_t kTotalSamples = {d['total_samples']};",
    f"constexpr int kChunkCount = {len(chunks)};",
    f"constexpr int kPcmCount = {len(pcm)};",
    "",
    "constexpr int16_t kPcm[] = {",
]
for i in range(0, len(pcm), 16):
    out.append("    " + ", ".join(str(v) for v in pcm[i:i + 16]) + ",")
out += ["};", "", "constexpr const char* kChunksHex[] = {"]
for c in chunks:
    out.append(f'    "{c}",')
out += ["};", "", "}  // namespace halo::test::golden", ""]
open(sys.argv[2], "w").write("\n".join(out))
print(f"{sys.argv[2]}: {len(chunks)} chunks, {len(pcm)} samples")
